package com.timez.chess.assist

import android.content.Context
import android.util.Log
import org.petero.droidfish.engine.EngineConfig
import org.petero.droidfish.engine.UCIEngine
import org.petero.droidfish.engine.UCIEngineBase
import org.petero.droidfish.player.EngineListener

import java.util.concurrent.Executors

/**
 * 分析引擎：直接驱动一个独立 pikafish UCI 进程（与游戏内引擎进程互不干扰）。
 */
class AnalysisEngine(
    private val context: Context,
    private val listener: Listener,
    searchDepth: Int = 20,
    private val maxPv: Int = 3,
    initialThreads: Int = Runtime.getRuntime().availableProcessors(),
) : AssistEngine {

    interface Listener {
        fun onEngineReady()
        fun onSearchUpdate(result: AnalysisResult)
        fun onSearchDone(result: AnalysisResult)
        fun onEngineError(message: String)
    }

    private val tag = "AnalysisEngine"
    private val executor = Executors.newSingleThreadExecutor { r ->
        Thread(r, "analysis-engine").apply { isDaemon = true }
    }
    private val engineListener = object : EngineListener {
        override fun reportEngineError(errMsg: String?) {
            Log.w(tag, "engine error: $errMsg")
            listener.onEngineError(errMsg ?: "引擎错误")
        }
        override fun notifyEngineName(engineName: String?) {}
        override fun notifySearchResult(searchId: Int, bestMove: String?, nextPonderMove: String?) {}
        override fun notifyEvalResult(searchId: Int, eval: Float) {}
        override fun notifyEngineInitialized() {}
    }

    @Volatile private var engine: UCIEngine? = null
    @Volatile private var ready = false
    @Volatile private var started = false

    @Volatile private var pendingFen: String? = null
    private val lock = Object()

    @Volatile private var searchDepth: Int = searchDepth.coerceIn(6, 40)
    @Volatile private var hashMb: Int = 256
    @Volatile private var appliedHash = -1
    @Volatile private var threads: Int = initialThreads.coerceIn(1, 128)
    @Volatile private var appliedThreads = -1

    override fun setSearchDepth(depth: Int) {
        searchDepth = depth.coerceIn(6, 40)
    }

    override fun setHash(mb: Int) {
        hashMb = mb
    }

    override fun setThreads(n: Int) {
        threads = n.coerceIn(1, 128)
    }

    override fun start() {
        synchronized(lock) {
            if (started) return
            started = true
        }
        executor.execute {
            var attempt = 0
            while (!ready && !shuttingDown && attempt < 2) {
                attempt++
                try {
                    doStart()
                } catch (e: Exception) {
                    Log.e(tag, "engine start failed (attempt $attempt)", e)
                    if (attempt >= 2) {
                        listener.onEngineError("引擎启动失败：${e.message ?: "未知原因"}（请重新连线重试）")
                    }
                }
                if (!ready && !shuttingDown && attempt < 2) {
                    runCatching { engine?.shutDown() }
                    engine = null
                    try { Thread.sleep(1200) } catch (e: InterruptedException) { return@execute }
                }
            }
            if (!ready) return@execute

            while (!shuttingDown) {
                val fen = pendingFen
                if (fen == null) {
                    synchronized(lock) {
                        try { lock.wait(300) } catch (e: InterruptedException) {
                            Thread.currentThread().interrupt(); return@execute
                        }
                    }
                    continue
                }
                pendingFen = null
                searchOnce(fen)
            }
        }
    }

    private fun doStart() {
        val ec = EngineConfig().apply { workDir = context.filesDir.absolutePath }
        val eng: UCIEngine = UCIEngineBase.getEngine("pikafish", ec, engineListener)
            ?: throw IllegalStateException("无法创建 pikafish 引擎")
        engine = eng
        eng.in

itialize()

        eng.writeLineToEngine("uci")

        var uciok = false
        var elapsed = 0L
        val dl = 200L
        while (!uciok && elapsed < 10000) {
            val line = eng.readLineFromEngine(dl.toInt()) ?: throw IllegalStateException("引擎进程意外退出")
            elapsed += dl
            if (line.isEmpty()) continue
            val tokens = line.trim().split(Regex("\\s+"))
            when {
                tokens[0] == "uciok" -> uciok = true
                tokens[0] == "id" || tokens[0] == "option" -> eng.registerOption(tokens.toTypedArray())
            }
        }
        if (!uciok) throw IllegalStateException("引擎握手超时（uciok），多为 CPU/兼容性问题")

        eng.initConfig(ec)

        eng.setOption("EvalFile", "libpikafish.nnue.so")
        eng.setOption("Threads", threads)
        appliedThreads = threads
        eng.setOption("Hash", hashMb)
        appliedHash = hashMb
        eng.setOption("MultiPV", maxPv)

        eng.writeLineToEngine("ucinewgame")
        eng.writeLineToEngine("isready")
        var readyOk = false
        elapsed = 0L
        while (!readyOk && elapsed < 15000) {
            val line = eng.readLineFromEngine(dl.toInt()) ?: throw IllegalStateException("引擎进程意外退出")
            elapsed += dl
            if (line.trim() == "readyok") readyOk = true
        }
        if (!readyOk) throw IllegalStateException("引擎就绪握手失败（readyok）")
        ready = true
        Log.i(tag, "analysis engine ready, threads=$threads hash=$hashMb")
        listener.onEngineReady()
    }

    @Volatile private var shuttingDown = false

    private fun searchOnce(fen: String) {
        val eng = engine ?: return
        val lines = LinkedHashMap<Int, MutableAnalysisLine>()
        if (appliedHash != hashMb) {
            eng.setOption("Hash", hashMb)
            appliedHash = hashMb
        }
        if (appliedThreads != threads) {
            eng.setOption("Threads", threads)
            appliedThreads = threads
        }
        eng.writeLineToEngine("position fen $fen")
        eng.writeLineToEngine("go depth $searchDepth")

        val deadline = System.currentTimeMillis() + 60000
        while (System.currentTimeMillis() < deadline) {
            val line = eng.readLineFromEngine(250) ?: return
            val tokens = line.trim().split(Regex("\\s+"))
            if (tokens.isEmpty()) continue
            if (tokens[0] == "info") {
                if (tokens.contains("string")) Log.i(tag, "engine: ${line.trim()}")
                parseInfo(tokens)?.let { ml ->
                    lines[ml.multiPv] = ml
                    val redGo = try { fen.split(" ")[1] != "b" } catch (e: Exception) { true }
                    listener.onSearchUpdate(AnalysisResult(fen, redGo, null,
                        lines.values.sortedBy { it.multiPv }.map { it.toAnalysisLine() }))
                }
            } else if (tokens[0] == "bestmove") {
                val bm = if (tokens.size > 1) tokens[1] else null
                val redGo = try { fen.split(" ")[1] != "b" } catch (e: Exception) { true }
                listener.onSearchDone(AnalysisResult(fen, redGo, bm,
                    lines.values.sortedBy { it.multiPv }.map { it.toAnalysisLine() }))
                return
            }
        }
        eng.writeLineToEngine("stop")
        val dl2 = System.currentTimeMillis() + 1500
        while (System.currentTimeMillis() < dl2) {
            val line = eng.readLineFromEngine(250) ?: return
            val tokens = line.trim().split(Regex("\\s+"))
            if (tokens.isEmpty()) continue
            if (tokens[0] == "bestmove") {
                val bm = if (tokens.size > 1) tokens[1] else null
                val redGo = try { fen.split(" ")[1] != "b" } catch (e: Exception) { true }
                listener.onSearchDone(AnalysisResult(fen, redGo, bm,
                    lines.values.sortedBy { it.multiPv }.map { it.toAnalysisLine() }))
                return
            }
        }
        listener.onSearchDone(AnalysisResult(fen, true,

null,
           lines.values.sortedBy { it.multiPv }.map { it.toAnalysisLine() }))
   }

   private class MutableAnalysisLine(val multiPv: Int) {
       var depth = 0
       var scoreCp = 0
       var mateIn: Int? = null
       var pv: List<String> = emptyList()
       fun toAnalysisLine(): AnalysisLine = AnalysisLine(multiPv, depth, scoreCp, mateIn, pv)
   }

   private fun parseInfo(tokens: List<String>): MutableAnalysisLine? {
       var mu

ltiPv = 1
        var depth = 0
        var scoreCp: Int? = null
        var mateIn: Int? = null
        var pv: List<String> = emptyList()
        var i = 1
        while (i < tokens.size) {
            when (tokens[i]) {
                "depth" -> if (i + 1 < tokens.size) { depth = tokens[i + 1].toIntOrNull() ?: depth; i++ }
                "multipv" -> if (i + 1 < tokens.size) { multiPv = tokens[i + 1].toIntOrNull() ?: multiPv; i++ }
                "score" -> if (i + 2 < tokens.size) {
                    when (tokens[i + 1]) {
                        "cp" -> { scoreCp = tokens[i + 2].toIntOrNull() ?: 0; i += 2 }
                        "mate" -> { mateIn = tokens[i + 2].toIntOrNull(); scoreCp = 0; i += 2 }
                    }
                }
                "pv" -> { pv = tokens.subList(i + 1, tokens.size).filter { it.length == 4 }; i = tokens.size }
                "currmove" -> i = tokens.size
            }
            i++
        }
        if (scoreCp == null && mateIn == null) return null
        return MutableAnalysisLine(multiPv).apply {
            this.depth = depth
            this.scoreCp = scoreCp ?: 0
            this.mateIn = mateIn
            this.pv = pv
        }
    }

    override fun request(fen: String) {
        pendingFen = fen
        val eng = engine
        if (eng != null && ready) {
            eng.writeLineToEngine("stop")
        }
        synchronized(lock) { lock.notifyAll() }
    }

    override fun shutdown() {
        shuttingDown = true
        ready = false
        synchronized(lock) { lock.notifyAll() }
        try { engine?.shutDown() } catch (e: Exception) { Log.w(tag, "shutDown failed", e) }
        engine = null
        executor.shutdownNow()
    }
}

package com.timez.chess.assist

/**
 * 引擎分析结果模型。
 * 注意：pikafish 的 info score 以"当前走子方（side to move）"视角给出，本模块统一换算为红方视角。
 */
class AnalysisLine(
    val multiPv: Int = 1,
    val depth: Int = 0,
    /** 红方视角分数（centipawn），正数红方有利 */
    val redScoreCp: Int = 0,
    /** 红方视角杀棋：正=红方将杀，负=黑方将杀；null=非杀棋 */
    val mateIn: Int? = null,
    /** 变着（UCCI 4 字母） */
    val pv: List<String> = emptyList(),
) {
    /** 显示的分数文本，如 "+2.60"、"M3"、"-M2" */
    fun scoreText(): String {
        val m = mateIn
        if (m != null) return if (m > 0) "M$m" else "-M${-m}"
        return if (redScoreCp >= 0) "+%.2f".format(redScoreCp / 100.0)
        else "%.2f".format(redScoreCp / 100.0)
    }
}

class AnalysisResult(
    val fen: String,
    val redGo: Boolean,
    val bestMove: String?,
    val lines: List<AnalysisLine>,
) {
    val bestLine: AnalysisLine? get() = lines.firstOrNull()

    /** 首个走法（bestmove 的 UCCI） */
    val bestUcci: String? get() = bestMove ?: bestLine?.pv?.firstOrNull()
}

package com.timez.chess.assist

import com.timez.chess.gamelogic.Piece
import kotlin.text.iterator

/**
 * 纯 JVM 的中国象棋棋盘抽象。
 * 约定与项目 gamelogic.Board 一致：piece[y][x]，y=0 为黑方底线，y=9 为红方底线（红在下即标准视角）。
 * 本文件不依赖任何 Android 类，便于单元测试。
 */
object AssistBoard {
    const val W = 9
    const val H = 10

    /** 标准开局 FEN（xqbase 格式，红先） */
    const val START_FEN = "rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/1C5C1/9/RNBAKABNR w - - 0 1"

    /** 标准开局局面，piece[y][x]，红在 y=9 底部 */
    /**
     * 比对两个局面的"走子特征"：
     * - occupiedToEmpty：从有子变空的格子数（真实走子必为 1，即起点）
     * - emptyToOccupied：从空变有子的格子数（无吃子时为 1，吃子时为 0）
     * - typeChange：同格有子但类型变了（吃子时终点 1 格，或识别抖动）
     * 返回 intArrayOf(occupiedToEmpty, emptyToOccupied, typeChange)
     */
    fun moveDiff(a: Array<IntArray>, b: Array<IntArray>): IntArray {
        var occToEmpty = 0
        var emptyToOcc = 0
        var typeChange = 0
        for (y in 0 until H) for (x in 0 until W) {
            val pa = a[y][x]
            val pb = b[y][x]
            if (pa == pb) continue
            when {
                pa != Piece.EMPTY && pb == Piece.EMPTY -> occToEmpty++
                pa == Piece.EMPTY && pb != Piece.EMPTY -> emptyToOcc++
                else -> typeChange++
            }
        }
        return intArrayOf(occToEmpty, emptyToOcc, typeChange)
    }

    fun canonicalStart(): Array<IntArray> {
        val p = Array(H) { IntArray(W) }
        for (x in 0 until W) {
            p[0][x] = when (x) {
                0, 8 -> Piece.BJU
                1, 7 -> Piece.BMA
                2, 6 -> Piece.BXIANG
                3, 5 -> Piece.BSHI
                else -> Piece.BJIANG
            }
        }
        p[2][1] = Piece.BPAO
        p[2][7] = Piece.BPAO
        for (x in 0 until W step 2) p[3][x] = Piece.BZU
        for (x in 0 until W step 2) p[6][x] = Piece.WBING
        p[7][1] = Piece.WPAO
        p[7][7] = Piece.WPAO
        for (x in 0 until W) {
            p[9][x] = when (x) {
                0, 8 -> Piece.WJU
                1, 7 -> Piece.WMA
                2, 6 -> Piece.WXIANG
                3, 5 -> Piece.WSHI
                else -> Piece.WSHUAI
            }
        }
        return p
    }

    fun clone(p: Array<IntArray>): Array<IntArray> = Array(H) { p[it].clone() }

    fun equal(a: Array<IntArray>, b: Array<IntArray>): Boolean {
        for (y in 0 until H) for (x in 0 until W) if (a[y][x] != b[y][x]) return false
        return true
    }

    /** piece[y][x] -> xqbase FEN 盘面 + 走子方 */
    fun toFen(pieces: Array<IntArray>, redGo: Boolean): String {
        val sb = StringBuilder()
        for (y in 0 until H) {
            var zeros = 0
            for (x in 0 until W) {
                val p = pieces[y][x]
                if (p == Piece.EMPTY) zeros++
                else {
                    if (zeros > 0) { sb.append(zeros); zeros = 0 }
                    sb.append(Piece.pieceCharMap[p])
                }
            }
            if (zeros > 0) sb.append(zeros)
            if (y < H - 1) sb.append('/')
        }
        return "$sb ${if (redGo) "w" else "b"} - - 0 1"
    }

    fun piecesFromFen(fen: String): Array<IntArray> {
        val p = Array(H) { IntArray(W) }
        val board = fen.trim().split(' ')[0]
        var x = 0
        var y = 0
        for (c in board) {
            when {
                c == '/' -> { x = 0; y++ }
                c in '0'..'9' -> { x += c - '0' }
                else -> { p[y][x] = Piece.pieceValueMap[c] ?: Piece.EMPTY; x++ }
            }
        }
        return p
    }

    /**
     * 应用一个 ucci 着法（如 "h2e2"）到 FEN 局面，返回行棋方翻转后的新 FEN。
     * 着法非法或起点无子时原样返回。
     */    fun applyUcci(fen: String, ucci: String): String {

if (ucci.length < 4) return fen
    val fx = ucci[0] - 'a'
    val fy = 9 - (ucci[1] - '0')
    val tx = ucci[2] - 'a'
    val ty = 9 - (ucci[3] - '0')
    if (fx !in 0 until W || fy !in 0 until H || tx !in 0 until W || ty !in 0 until H) return fen
    val board = piecesFromFen(fen)
    val piece = board[fy][fx]
    if (piece == Piece.EMPTY) return fen
    board[ty][tx] = piece
    board[fy][fx] = Piece.EMPTY
    val nextRedGo = fen.trim().split(' ').getOrNull(1) != "w"
    return toFen(board, nextRedGo)
}

/**
 * 推断"刚走子的一方"：对比旧/新局面。返回红(1)、黑(0)或 null(无法确定)。
 * 规则：新增棋子（目标格）所属阵营即移动方；无新增（重排/异常）则尝试用移除方补。
 */
fun movedSide(old: Array<IntArray>, new: Array<IntArray>): Int? {
    var addedSide: Int? = null
    var removedSide: Int? = null
    for (y in 0 until H) for (x in 0 until W) {
        val o = old[y][x]
        val n = new[y][x]
        if (o == n) continue
        if (n != Piece.EMPTY) {
            val s = if (Piece.isRed(n)) 1 else 0
            if (addedSide != null && addedSide != s) return null
            addedSide = s
        }
        if (o != Piece.EMPTY) {
            val s = if (Piece.isRed(o)) 1 else 0
            if (removedSide != null && removedSide != s) return null
            removedSide = s
        }
    }
    return addedSide ?: removedSide
}

/**
 * 宽容合法性校验：只拦"严重异常"帧（缺帅/将、总子数超限、同方帅>2）。
 * 棋子数量上限不再严格限制——YOLO 中局难免把车/马混淆，严格校验会让
 * 90% 的正常帧被拒，导致"识别不稳定"。
 */
fun validate(pieces: Array<IntArray>): List<String> {
    val issues = mutableListOf<String>()
    val counts = IntArray(Piece.BZU + 1)
    for (y in 0 until H) for (x in 0 until W) {
        val p = pieces[y][x]
        if (p != Piece.EMPTY) counts[p]++
    }
    // 只拦真正离谱的：帅/将必须存在，且不能有 3 个以上
    val redKing = counts[Piece.WSHUAI]
    val blackKing = counts[Piece.BJIANG]
    if (redKing < 1) issues.add("红帅缺失")
    if (blackKing < 1) issues.add("黑将缺失")
    if (redKing > 2) issues.add("红帅过多:$redKing")
    if (blackKing > 2) issues.add("黑将过多:$blackKing")

    var total = 0
    for (c in counts) total += c
    if (total > 32) issues.add("总子数超限:$total")

    // 红/黑任一方棋子总数超过 16（初始上限），说明识别把对方棋子算到了本方
    var redTotal = 0
    var blackTotal = 0
    for (y in 0 until H) for (x in 0 until W) {
        val p = pieces[y][x]
        if (p == Piece.EMPTY) continue
        if (Piece.isRed(p)) redTotal++ else blackTotal++
    }
    if (redTotal > 16) issues.add("红方子数超限:$redTotal")
    if (blackTotal > 16) issues.add("黑方子数超限:$blackTotal")

    return issues
}

/** 与开局对照一致的子数（用于"开局检测"）；开局局面只读缓存，避免每帧重建 */
private val startBoard = canonicalStart()

fun matchStartCount(pieces: Array<IntArray>): Int {
    var n = 0
    for (y in 0 until H) for (x in 0 until W) {

    if (pieces[y][x] != Piece.EMPTY && pieces[y][x] == startBoard[y][x]) n++
        }
        return n
    }
}

package com.timez.chess.assist

import android.content.Context

/**
 * 连线功能的持久化配置（SharedPreferences）。
 */
class AssistConfig(context: Context) {
    private val sp = context.getSharedPreferences("assist_settings", Context.MODE_PRIVATE)

    /** 最近一次识别时的帧尺寸（悬浮窗遮挡判断用：把归一化棋盘框换算回像素） */
    var frameSize: Pair<Int, Int>
        get() {
            val w = sp.getInt(KEY_FRAME_W, 0)
            val h = sp.getInt(KEY_FRAME_H, 0)
            return w to h
        }
        set(value) {
            sp.edit().putInt(KEY_FRAME_W, value.first).putInt(KEY_FRAME_H, value.second).apply()
        }

    /** 稳定确认帧数（1..8） */
    var confirmCount: Int
        get() = sp.getInt(KEY_CONFIRM, 2).coerceIn(1, 8)
        set(value) { sp.edit().putInt(KEY_CONFIRM, value.coerceIn(1, 8)).apply() }

    /** 悬浮窗上次位置（左上角，归一化 0..1），未设置则默认 */
    var overlayPos: Pair<Float, Float>
        get() = sp.getFloat(KEY_OVERLAY_X, -1f) to sp.getFloat(KEY_OVERLAY_Y, -1f)
        set(value) {
            sp.edit().putFloat(KEY_OVERLAY_X, value.first).putFloat(KEY_OVERLAY_Y, value.second).apply()
        }

    /** 搜索深度（与对弈"固定深度"制式一致，默认 20） */
    var searchDepth: Int
        get() = sp.getInt(KEY_SEARCH_DEPTH, 20)
        set(value) { sp.edit().putInt(KEY_SEARCH_DEPTH, value.coerceIn(6, 40)).apply() }

    // ==================== 引擎模式（本地 / 远程） ====================

    /** 引擎模式："local" / "remote"，默认 "local" */
    var engineMode: String
        get() = sp.getString(KEY_ENGINE_MODE, "local") ?: "local"
        set(value) {
            val v = if (value == "remote") "remote" else "local"
            sp.edit().putString(KEY_ENGINE_MODE, v).apply()
        }

    /** 远程引擎主机（电脑局域网 IP），默认空，由用户在应用内输入 */
    var remoteHost: String
        get() = sp.getString(KEY_REMOTE_HOST, "") ?: ""
        set(value) { sp.edit().putString(KEY_REMOTE_HOST, value.trim()).apply() }

    /** 远程引擎端口，默认 0（未设置），由用户在应用内输入 */
    var remotePort: Int
        get() = sp.getInt(KEY_REMOTE_PORT, 0)
        set(value) { sp.edit().putInt(KEY_REMOTE_PORT, value.coerceIn(0, 65535)).apply() }

    /** 远程配置是否有效（IP 非空且端口在合法范围） */
    val isRemoteValid: Boolean
        get() = remoteHost.isNotBlank() && remotePort in 1..65535

    // ==================== 其他 ====================

    // /** 引擎 Hash（MB，与对弈设置同口径；面板按钮循环 256→512→1024→2048） */
    var hashMb: Int
        get() = sp.getInt(KEY_HASH_MB, 256)
        set(value) { sp.edit().putInt(KEY_HASH_MB, value).apply() }
    /** 棋盘皮肤："auto"（自动检测）/"wood"/"green"/"white" */

    /** 引擎线程数（本地/远程共用），默认取手机核心数 */
    var threads: Int
        get() = sp.getInt(KEY_THREADS, Runtime.getRuntime().availableProcessors())
            .coerceIn(1, 128)
        set(value) { sp.edit().putInt(KEY_THREADS, value.coerceIn(1, 128)).apply() }

    var boardSkin: String
        get() = sp.getString(KEY_BOARD_SKIN, "auto") ?: "auto"
        set(value) { sp.edit().putString(KEY_BOARD_SKIN, value).apply() }

    companion object {
        private const val KEY_FRAME_W = "frame_w"
        private const val KEY_FRAME_H = "frame_h"
        private const val KEY_CONFIRM = "confirm_count"
        private const val KEY_OVERLAY_X = "overlay_x"
        private const val KEY_OVERLAY_Y = "overlay_y"
        private const val KEY_SEARCH_DEPTH = "search_depth"
