package com.timez.chess.assist

/**
 * 棋盘格点映射：由"棋盘左上角交点"与"右下角交点"两个对角交点的屏幕坐标（归一化 0..1）表达
 * 9×10 网格的覆盖范围。纯 JVM，无 Android 依赖。
 *
 * 连线功能中由 YOLO 检出的棋盘外框换算而来，用于悬浮窗遮挡判断等场景。
 */
class BoardGrid(
    val nx0: Double,
    val ny0: Double,
    val nx1: Double,
    val ny1: Double,
) {
    init {
        validateOrThrow()
    }

    private fun validateOrThrow() {
        if (nx0 < 0 || ny0 < 0 || nx1 > 1 || ny1 > 1) {
            throw IllegalArgumentException("grid points must be inside normalized screen: ($nx0,$ny0)-($nx1,$ny1)")
        }
        if (nx1 <= nx0 || ny1 <= ny0) {
            throw IllegalArgumentException("grid corners reversed: ($nx0,$ny0)-($nx1,$ny1)")
        }
    }

    companion object {
        /**
         * 由两个对角交点的像素坐标构建（左上/右下、右上/左下等任意组合都可，内部统一为左上/右下）。
         */
        fun fromPxCorners(xa: Double, ya: Double, xb: Double, yb: Double,
                          frameW: Int, frameH: Int): BoardGrid {
            val x0 = minOf(xa, xb)
            val x1 = maxOf(xa, xb)
            val y0 = minOf(ya, yb)
            val y1 = maxOf(ya, yb)
            return BoardGrid(x0 / frameW, y0 / frameH, x1 / frameW, y1 / frameH)
        }
    }
}

package com.timez.chess.assist

import com.timez.chess.gamelogic.Piece
import kotlin.math.roundToInt
import kotlin.math.sqrt

/**
 * YOLO 检测结果 -> 9×10 棋盘映射（纯 JVM）。
 *
 * 移植自 VinXiangQi 的 GetBoardFromPrediction 并加强：
 * 1. 优先用模型的 board 框做网格锚点（宽/8、高/9 即格距）；
 * 2. board 缺失或形状异常时，用棋子中心点包围盒兜底（需有足够棋子且间距一致）；
 * 3. 棋子中心 round 到最近交点，越界丢弃，同格冲突保留高分者；
 * 4. 朝向由两个王的位置推断（帅在下=STANDARD）。
 */
object DetectionBoardMapper {

    class MappedBoard(
        /** 屏幕布局 [gy][gx]（gy=0 为屏幕顶部），元素为 Piece 常量或 EMPTY */
        val screenRaw: Array<IntArray>,
        /** canonical 布局（红恒在 y=9） */
        val canonical: Array<IntArray>,
        val orientation: Orientation,
        /** 由棋盘框换算的归一化网格（供悬浮窗遮挡判断等复用） */
        val grid: BoardGrid?,
        val pieceCount: Int,
        val avgScore: Double,
        /** 识别日志：被丢弃的越界/重复棋子数 */
        val dropped: Int,
    )

    /**
     * 单帧最少"棋子检测数"：低于该值不值得映射（整屏无棋盘）。残局可低至 3 子
     * （帅仕 vs 将），故不能沿用 10——那会把稀疏残局永远拒之门外；
     * 结构合法性由 AssistBoard.validate、瞬时坏帧由 BoardTracker 的多帧确认把关。
     */
    fun map(dets: List<YoloDetection>, frameW: Int, frameH: Int, minPieces: Int = 3): MappedBoard? {
        val pieces = dets.filter { !it.isBoard }
        if (pieces.size < minPieces) return null

        val boardDet = dets.filter { it.isBoard }.maxByOrNull { it.score }
        val avgW = pieces.map { it.w }.average()
        val avgH = pieces.map { it.h }.average()

        var bx0 = 0.0; var by0 = 0.0; var bx1 = 0.0; var by1 = 0.0
        var anchored = false
        if (boardDet != null) {
            val x0 = boardDet.cx - boardDet.w / 2
            val y0 = boardDet.cy - boardDet.h / 2
            val x1 = boardDet.cx + boardDet.w / 2
            val y1 = boardDet.cy + boardDet.h / 2
            val ratio = (x1 - x0) / (y1 - y0)
            if (ratio in 0.7..1.3 && (x1 - x0) >= avgW * 7 && (y1 - y0) >= avgH * 8) {
                bx0 = x0; by0 = y0; bx1 = x1; by1 = y1
                anchored = true
            }
        }
        if (!anchored) {
            // 兜底：棋子中心包围盒（至少需要 20 子才可信）
            if (pieces.size < 20) return null
            val minX = pieces.minOf { it.cx }; val maxX = pieces.maxOf { it.cx }
            val minY = pieces.minOf { it.cy }; val maxY = pieces.maxOf { it.cy }
            val w = maxX - minX; val h = maxY - minY
            if (w <= 0 || h <= 0) return null
            if (w / h !in 0.7..1.3) return null
            // 最小棋子间距应与包围盒跨度相容（近似 8 列 9 行的等距网格）
            var minDist = Double.MAX_VALUE
            for (i in pieces.indices) for (j in i + 1 until pieces.size) {
                val dx = pieces[i].cx - pieces[j].cx
                val dy = pieces[i].cy - pieces[j].cy
                val d = sqrt(dx * dx + dy * dy)
                if (d < minDist) minDist = d
            }
            if (h < minDist * 8.0 || w < minDist * 7.0) return null
            bx0 = minX; by0 = minY; bx1 = maxX; by1 = maxY
        }

        val gridW = (bx1 - bx0) / 8.0
        val gridH = (by1 - by0) / 9.0
        if (gridW <= 0 || gridH <= 0) return null

        val cells = Array(AssistBoard.H) { IntArray(AssistBoard.W) }
        val cellScore = Array(AssistBoard.H) { DoubleArray(AssistBoard.W) }
        var dropped = 0
        var scoreSum = 0.0
        for (p in pieces) {
            val col = ((p.cx - bx0) / gridW).roundToInt()
            val row = ((p.cy - by0) / gridH).roundToInt()
            if (col !in 0 until AssistBoard.W || row !in 0 until AssistBoard.H) { dropped++; continue }

if (cells[row][col] != Piece.EMPTY && cellScore[row][col] >= p.score) { dropped++; continue }
            if (cells[row][col] != Piece.EMPTY) scoreSum -= cellScore[row][col]
            cells[row][col] = p.piece
            cellScore[row][col] = p.score
            scoreSum += p.score
        }
        val pieceCount = cells.sumOf { row -> row.count { it != Piece.EMPTY } }

        val orientation = detectOrientation(cells) ?: Orientation.STANDARD
        val canonical = toCanonical(cells, orientation)

        val grid = try {
            BoardGrid.fromPxCorners(
                bx0.coerceIn(0.0, frameW.toDouble()), by0.coerceIn(0.0, frameH.toDouble()),
                bx1.coerceIn(0.0, frameW.toDouble()), by1.coerceIn(0.0, frameH.toDouble()),
                frameW, frameH)
        } catch (e: Exception) { null }

        return MappedBoard(cells, canonical, orientation, grid, pieceCount,
            if (pieceCount > 0) scoreSum / pieceCount else 0.0, dropped)
    }

    /** 双王位置判定屏幕朝向（帅在下=STANDARD，独立实现保持纯 JVM 无耦合） */
    fun detectOrientation(raw: Array<IntArray>): Orientation? {
        var redRow = -1
        var blackRow = -1
        for (gy in 0 until AssistBoard.H) for (gx in 0 until AssistBoard.W) {
            when (raw[gy][gx]) {
                Piece.WSHUAI -> redRow = gy
                Piece.BJIANG -> blackRow = gy
            }
        }
        if (redRow >= 0 && redRow > 4) return Orientation.STANDARD
        if (blackRow >= 0 && blackRow > 4) return Orientation.FLIPPED
        if (redRow >= 0 && redRow <= 4) return Orientation.FLIPPED
        if (blackRow >= 0 && blackRow <= 4) return Orientation.STANDARD
        return null
    }

    /** 屏幕 raw 布局 -> 内部 canonical（红恒在 y=9） */
    fun toCanonical(raw: Array<IntArray>, orientation: Orientation): Array<IntArray> {
        val out = Array(AssistBoard.H) { IntArray(AssistBoard.W) }
        for (gy in 0 until AssistBoard.H) for (gx in 0 until AssistBoard.W) {
            val p = raw[gy][gx]
            if (p == Piece.EMPTY) continue
            when (orientation) {
                Orientation.STANDARD -> out[gy][gx] = p
                Orientation.FLIPPED -> out[AssistBoard.H - 1 - gy][AssistBoard.W - 1 - gx] = p
            }
        }
        return out
    }
}

package com.timez.chess.assist

import com.timez.chess.gamelogic.Board
import com.timez.chess.gamelogic.Move

/**
 * UCCI 走法 -> 中文着法（复用项目 gamelogic 的 Move.getChsString 规则）。
 */
object MoveChinese {
    /** 返回如 "炮二平五 (h2e2)"；解析失败则原样返回 UCCI */
    fun describe(fen: String, ucci: String): String {
        val board = Board()
        if (!board.restoreFromFEN(fen)) return ucci
        val m = Move(board)
        if (m.fromUCCIString(ucci)) {
            return "${m.getChsString()} ($ucci)"
        }
        return ucci
    }
}

package com.timez.chess.assist

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Log
import com.timez.chess.gamelogic.Piece
import kotlin.collections.iterator
import kotlin.math.sqrt

/**
 * 模板匹配棋子识别器。
 * YOLO 只负责给出棋盘线框位置，本类负责在框内 9×10 个交叉点上，
 * 用归一化互相关（NCC）比对 14 个棋子模板，输出 canonical 棋盘。
 */
class PieceMatcher(private val context: Context) {

    companion object {
        private const val TAG = "PieceMatcher"
        private const val TSIZE = 48
        private const val MATCH_THRESHOLD = 0.50f

        private val CLASSES = arrayOf(
            "r_che", "r_ma", "r_xiang", "r_shi", "r_shuai", "r_pao", "r_bing",
            "b_che", "b_ma", "b_xiang", "b_shi", "b_jiang", "b_pao", "b_zu"
        )
        private val SKINS = arrayOf("wood", "green", "white")

        private val CLASS_TO_PIECE: Map<String, Int> = mapOf(
            "r_che" to Piece.WJU, "r_ma" to Piece.WMA, "r_xiang" to Piece.WXIANG,
            "r_shi" to Piece.WSHI, "r_shuai" to Piece.WSHUAI, "r_pao" to Piece.WPAO,
            "r_bing" to Piece.WBING,
            "b_che" to Piece.BJU, "b_ma" to Piece.BMA, "b_xiang" to Piece.BXIANG,
            "b_shi" to Piece.BSHI, "b_jiang" to Piece.BJIANG, "b_pao" to Piece.BPAO,
            "b_zu" to Piece.BZU,
        )
    }

    private val templates: Map<String, Map<String, FloatArray>>

    init {
        val loaded = mutableMapOf<String, Map<String, FloatArray>>()
        for (skin in SKINS) {
            val skinMap = mutableMapOf<String, FloatArray>()
            for (cls in CLASSES) {
                try {
                    context.assets.open("templates/$skin/$cls.png").use { ins ->
                        val bmp = BitmapFactory.decodeStream(ins)
                        if (bmp != null) {
                            skinMap[cls] = extractGrayFromBitmap(bmp)
                            bmp.recycle()
                        }
                    }
                } catch (e: Exception) {
                    Log.w(TAG, "load failed: $skin/$cls: ${e.message}")
                }
            }
            if (skinMap.size >= 12) {
                loaded[skin] = skinMap
                Log.i(TAG, "loaded skin $skin: ${skinMap.size} classes")
            }
        }
        templates = loaded
        Log.i(TAG, "available skins: ${templates.keys}")
    }

    data class MatchResult(
        val canonical: Array<IntArray>,
        val skin: String,
        val score: Float,
        val pieceCount: Int,
    )

    /**
     * @param nx0,ny0,nx1,ny1 棋盘线框归一化坐标（左上、右下）
     * @param preferredSkin 指定皮肤（"wood"/"green"/"white"）；null 或 "auto" 时跑全部皮肤取最优
     */
    fun match(
        frame: Frame,
        nx0: Float, ny0: Float, nx1: Float, ny1: Float,
        preferredSkin: String? = null,
    ): MatchResult? {
        if (templates.isEmpty()) return null

        val x0 = (nx0 * frame.width).toInt()
        val y0 = (ny0 * frame.height).toInt()
        val x1 = (nx1 * frame.width).toInt()
        val y1 = (ny1 * frame.height).toInt()
        if (x1 - x0 < 100 || y1 - y0 < 100) return null

        val colGap = (x1 - x0) / 8f
        val rowGap = (y1 - y0) / 9f
        val half = (minOf(colGap, rowGap) * 0.40f).toInt()

        val skinList: List<String> = if (!preferredSkin.isNullOrEmpty() && preferredSkin != "auto"
            && templates.containsKey(preferredSkin)) {
            listOf(preferredSkin)
        } else {
            templates.keys.toList()
        }

        var best: MatchResult? = null
        for (skin in skinList) {
            val tplMap = templates[skin] ?: continue
            val board = Array(10) { IntArray(9) }
            var scoreSum = 0f
            var count = 0
            for (row in 0 until 10) {
                for (col in 0 until 9) {

                    val cx = (x0 + col * colGap).toInt()
                    val cy = (y0 + row * rowGap).toInt()
                    val sx = (cx - half).coerceAtLeast(0)
                    val sy = (cy - half).coerceAtLeast(0)
                    val ex = (cx + half).coerceAtMost(frame.width)
                    val ey = (cy + half).coerceAtMost(frame.height)
                    if (ex - sx < 8 || ey - sy < 8) continue

                    val gray = extractGrayFromFrame(frame, sx, sy, ex, ey)
                    var bestCls: String? = null
                    var bestScore = -1f
                    for ((cls, tpl) in tplMap) {
                        val s = ncc(gray, tpl)
                        if (s > bestScore) { bestScore = s; bestCls = cls }
                    }
                    if (bestCls != null && bestScore > MATCH_THRESHOLD) {
                        board[row][col] = CLASS_TO_PIECE[bestCls] ?: Piece.EMPTY
                        scoreSum += bestScore
                        count++
                    }
                }
            }
            val avg = if (count > 0) scoreSum / count else 0f
            val r = MatchResult(board, skin, avg,

 count)
            if (best == null || r.pieceCount > best!!.pieceCount) best = r
        }
        return best
    }

    /** 从帧像素中裁取 x0..x1 / y0..y1 区域，缩放为 TSIZE×TSIZE 灰度归一化数组 */
    private fun extractGrayFromFrame(frame: Frame, x0: Int, y0: Int, x1: Int, y1: Int): FloatArray {
        val w = x1 - x0
        val h = y1 - y0
        val out = FloatArray(TSIZE * TSIZE)
        val stepX = w.toFloat() / TSIZE
        val stepY = h.toFloat() / TSIZE
        for (ty in 0 until TSIZE) {
            val sy = (y0 + ty * stepY).toInt().coerceIn(0, frame.height - 1)
            for (tx in 0 until TSIZE) {
                val sx = (x0 + tx * stepX).toInt().coerceIn(0, frame.width - 1)
                val p = frame.argb[sy * frame.width + sx]
                val r = (p shr 16) and 0xFF
                val g = (p shr 8) and 0xFF
                val b = p and 0xFF
                out[ty * TSIZE + tx] = (0.299f * r + 0.587f * g + 0.114f * b) / 255f
            }
        }
        normalize(out)
        return out
    }

    private fun extractGrayFromBitmap(bmp: Bitmap): FloatArray {
        val scaled = if (bmp.width != TSIZE || bmp.height != TSIZE) {
            Bitmap.createScaledBitmap(bmp, TSIZE, TSIZE, true)
        } else bmp
        val px = IntArray(TSIZE * TSIZE)
        scaled.getPixels(px, 0, TSIZE, 0, 0, TSIZE, TSIZE)
        val out = FloatArray(TSIZE * TSIZE)
        for (i in px.indices) {
            val p = px[i]
            val r = (p shr 16) and 0xFF
            val g = (p shr 8) and 0xFF
            val b = p and 0xFF
            out[i] = (0.299f * r + 0.587f * g + 0.114f * b) / 255f
        }
        if (scaled !== bmp) scaled.recycle()
        normalize(out)
        return out
    }

    private fun normalize(arr: FloatArray) {
        var sum = 0f
        for (v in arr) sum += v
        val mean = sum / arr.size
        var sq = 0f
        for (v in arr) sq += (v - mean) * (v - mean)
        val std = sqrt(sq / arr.size).coerceAtLeast(1e-6f)
        for (i in arr.indices) arr[i] = (arr[i] - mean) / std
    }

    private fun ncc(a: FloatArray, b: FloatArray): Float {
        var dot = 0f
        for (i in a.indices) dot += a[i] * b[i]
        return dot / a.size
    }
}

package com.timez.chess.assist

import kotlin.math.abs
import com.timez.chess.gamelogic.Piece

/**
 * 识别管线的共享类型（纯 JVM，无 Android 依赖）：
 * 帧输入、朝向、单帧识别结果、稳定帧跟踪器。
 */
class Frame(val width: Int, val height: Int, val argb: IntArray) {
    init {
        require(argb.size == width * height) { "frame pixel count mismatch" }
    }
}

enum class Orientation {
    /** 红方在下（标准朝向，屏幕下方阵营=红方） */
    STANDARD,
    /** 红方在上（换边/翻转朝向，屏幕下方阵营=黑方） */
    FLIPPED;
}

/**
 * 一帧识别结果。canonical 为项目内部约定（红恒定在 y=9），orientation 表示屏幕朝向。
 */
class RecognitionResult(
    val canonical: Array<IntArray>,
    val screenRaw: Array<IntArray>,
    val orientation: Orientation,
    val issues: List<String>,
    val unknownCells: Int,
    val recognizedPieces: Int,
    val avgScore: Double,
) {
    fun isValid(): Boolean = issues.isEmpty() && unknownCells == 0
}

/**
 * 稳定帧跟踪器：连续 confirmCount 帧出现同一局面才确认，并推断轮次/检测重开。
 */
class BoardTracker(private val confirmCount: Int = 2) {

    enum class Event {
        NEW_BOARD,
        SAME_BOARD,
        NEW_GAME,
        UNSTABLE,
    }

    var confirmed: RecognitionResult? = null
        private set

    @Volatile var redGo = true

    @Volatile var unstableStreak = 0
        private set

    private var candidate: RecognitionResult? = null
    private var candidateHits = 0
    /** 当前候选对应的“走子起点格”（x, y）；同一步走子才能连续累计 */
    private var candidateStartCell: Pair<Int, Int>? = null

    fun reset(redGoFirst: Boolean = true) {
        confirmed = null
        candidate = null
        candidateHits = 0
        candidateStartCell = null
        unstableStreak = 0
        redGo = redGoFirst
    }

    fun restore(result: RecognitionResult, redGoSide: Boolean) {
        confirmed = result
        redGo = redGoSide
        candidate = null
        candidateHits = 0
        candidateStartCell = null
        unstableStreak = 0
    }

    fun onFrame(res: RecognitionResult): Event {
        val prev = confirmed

        // 不合法帧
        if (!res.isValid()) {
            unstableStreak++
            return Event.UNSTABLE
        }

        // 首次确认
        if (prev == null) {
            if (candidate != null && AssistBoard.equal(res.canonical, candidate!!.canonical)) {
                candidateHits++
            } else {
                candidate = res
                candidateHits = 1
            }
            if (candidateHits >= confirmCount) {
                confirmed = candidate!!
                val first = candidate!!
                candidate = null
                candidateHits = 0
                unstableStreak = 0
                return if (AssistBoard.matchStartCount(first.canonical) >= 32)
                    Event.NEW_GAME else Event.NEW_BOARD
            }
            unstableStreak++
            return Event.UNSTABLE
        }

        // 重开检测
        if (AssistBoard.matchStartCount(res.canonical) >= 32 &&
            !AssistBoard.equal(res.canonical, prev.canonical)) {
            confirmed = res
            redGo = true
            candidate = null
            candidateHits = 0
            candidateStartCell = null
            unstableStreak = 0
            return Event.NEW_GAME
        }

        // 子数跳变门限
        val tol = maxOf(2, prev.recognizedPieces / 10)
        if (abs(res.recognizedPieces - prev.recognizedPieces) > tol) {
            candidate = null
            candidateHits = 0
            candidateStartCell = null
            unstableStreak++
            return Event.UNSTABLE
        }

        // 与已确认局面完全相同
        if (AssistBoard.equal(res.canonical, prev.canonical)) {
            candidate = null
            candidateHits = 0
            candidateStartCell = null
            unstableStreak = 0
            return Event.SAME_BOAR

