        }

        // 走子特征比对
        val diff = AssistBoard.moveDiff(res.canonical, prev.canonical)
        val occToEmpty = diff[0]
        val emptyToOcc = diff[1]
        val typeChange = diff[2]

        val isRealMove = (occToEmpty == 1) && (emptyToOcc + typeChange <= 2)

        if (!isRealMove) {
            // 抖动：小范围静默忽略，大范围报不稳定
            if (typeChange <= 4) {
                candidate = null
                candidateHits = 0
                candidateStartCell = null
                unstableStreak = 0
                return Event.SAME_BOARD
            }
            candidate = null
            candidateHits = 0
            candidateStartCell = null
            unstableStreak++
            return Event.UNSTABLE
        }

        // 找出起点格（从有子变空的唯一格子）
        var startCell: Pair<Int, Int>? = null
        for (y in 0 until AssistBoard.H) {
            for (x in 0 until AssistBoard.W) {
                val p0 = prev.canonical[y][x]
                val p1 = res.canonical[y][x]
                if (p0 != Piece.EMPTY && p1 == Piece.EMPTY) {
                    startCell = x to y
                    break
                }

      }
            if (startCell != null) break
        }
        if (startCell == null) {
            unstableStreak++
            return Event.UNSTABLE
        }

        // 候选确认：要求连续 confirmCount 帧都是“同一步走子”（起点格相同）
        if (candidateStartCell == startCell && candidate != null) {
            // 检查这次 res 与 candidate 是否仍是同一步（起点相同、终点一致）
            val stepDiff = AssistBoard.moveDiff(res.canonical, candidate!!.canonical)
            val stillSameStep = stepDiff[0] == 0 && stepDiff[1] == 0 && stepDiff[2] <= 2
            if (stillSameStep) {
                candidateHits++
            } else {
                candidate = res
                candidateHits = 1
            }
        } else {
            candidate = res
            candidateStartCell = startCell
            candidateHits = 1
        }

        if (candidateHits >= confirmCount) {
            val newBoard = candidate!!
            val moved = AssistBoard.movedSide(prev.canonical, newBoard.canonical)
            if (moved != null) {
                redGo = moved != 1
            }
            confirmed = newBoard
            candidate = null
            candidateHits = 0
            candidateStartCell = null
            unstableStreak = 0
            return Event.NEW_BOARD
        }
        unstableStreak++
        return Event.UNSTABLE
    }
}

package com.timez.chess.assist

import android.util.Log

import java.io.BufferedReader
import java.io.BufferedWriter
import java.io.IOException
import java.io.InputStreamReader
import java.io.OutputStreamWriter
import java.net.InetSocketAddress
import java.net.Socket
import java.net.SocketTimeoutException
import java.util.concurrent.Executors

/**
 * 远程分析引擎：通过 TCP 连接到电脑端的 RemoteUCI + Pikafish。
 * Listener 复用 [AnalysisEngine.Listener]，上层 UI 无需任何改动。
 */
class RemoteAnalysisEngine(
    private val host: String,
    private val port: Int,
    private val listener: AnalysisEngine.Listener,
    initialDepth: Int = 20,
    private val maxPv: Int = 3,
    initialThreads: Int = Runtime.getRuntime().availableProcessors(),
) : AssistEngine {

    private val tag = "RemoteAnalysisEngine"
    private val executor = Executors.newSingleThreadExecutor { r ->
        Thread(r, "remote-analysis-engine").apply { isDaemon = true }
    }

    @Volatile private var socket: Socket? = null
    @Volatile private var reader: BufferedReader? = null
    @Volatile private var writer: BufferedWriter? = null
    private val writeLock = Object()

    @Volatile private var ready = false
    @Volatile private var started = false
    @Volatile private var shuttingDown = false

    @Volatile private var pendingFen: String? = null
    private val lock = Object()

    @Volatile private var searchDepth: Int = initialDepth.coerceIn(6, 40)
    @Volatile private var hashMb: Int = 256
    @Volatile private var appliedHash = -1
    @Volatile private var threads: Int = initialThreads.coerceIn(1, 128)
    @Volatile private var appliedThreads = -1

    override fun setSearchDepth(depth: Int) {
        searchDepth = depth.coerceIn(6, 40)
    }

    override fun setHash(mb: Int) {
        hashMb = mb
        if (ready) {
            sendCommand("setoption name Hash value $mb")
            appliedHash = mb
        }
    }

    override fun setThreads(n: Int) {
        threads = n.coerceIn(1, 128)
        if (ready) {
            sendCommand("setoption name Threads value $threads")
            appliedThreads = threads
        }
    }

    override fun start() {
        synchronized(lock) {
            if (started) return
            started = true
        }
        executor.execute {
            var attempt = 0
            while (!ready && !shuttingDown && attempt < 2) {
                attempt++
                try {
                    doStart()
                } catch (e: Exception) {
                    Log.e(tag, "remote engine start failed (attempt $attempt)", e)
                    if (attempt >= 2) {
                        listener.onEngineError("远程引擎连接失败：${e.message ?: "未知原因"}")
                    }
                }
                if (!ready && !shuttingDown && attempt < 2) {
                    runCatching { closeSocket() }
                    try { Thread.sleep(1200) } catch (e: InterruptedException) { return@execute }
                }
            }
            if (!ready) return@execute

            while (!shuttingDown) {
                val fen = pendingFen
                if (fen == null) {
                    synchronized(lock) {
                        try { lock.wait(300) } catch (e: InterruptedException) {
                            Thread.currentThread().interrupt(); return@execute
                        }
                    }
                    continue
                }
                pendingFen = null
                try {
                    searchOnce(fen)
                } catch (e: Exception) {
                    Log.e(tag, "searchOnce failed", e)
                    listener.onEngineError("远程分析中断：${e.message ?: "连接断开"}")
                    ready = false
                    runCatching { closeSocket() }
                    try {
                        doStart()
                    } catch (ex: Exception) {

                Log.e(tag, "reconnect failed", ex)
                        listener.onEngineError("远程引擎重连失败，请检查电脑端 RemoteUCI 是否在运行")
                        return@execute
                    }
                }
            }
        }
    }

    private fun doStart() {
        closeSocket()
        val s = Socket()
        try {
            s.connect(InetSocketAddress(host, port), 5000)
        } catch (e: IOException) {
            s.close()
            throw IllegalStateException("无法连接 $host:$port（${e.message}）", e)
        }
        s.tcpNoDelay = true
        s.soTimeout = 30000
        socket = s
        reader = BufferedReader(InputStreamReader(s.getInputStream()))
        writer = BufferedWriter(OutputStreamWriter(s.getOutputStream()))

        sendCommand("uci")
        if (!waitForToken("uciok", 10000)) throw IllegalStateException("引擎握手超时（uciok）")

        sendCommand("setoption name Threads value $threads")
        appliedThreads = threads
        sendCommand("setoption name Hash value $hashMb")
        appliedHash = hashMb
        sendCommand("setoption name MultiPV value $maxPv")

        sendCommand("ucinewgame")
        sendCommand("isready")
        if (!waitForToken("readyok", 15000)) throw IllegalStateException("引擎就绪握手失败（readyok）")

        ready = true
        Log.i(tag, "remote analysis engine ready at $host:$port threads=$threads hash=$hashMb")
        listener.onEngineReady()
    }

    private fun waitForToken(token: String, timeoutMs: Long): Boolean {
        val r = reader ?: return false
        val deadline = System.currentTimeMillis() + timeoutMs
        while (System.currentTimeMillis() < deadline && !shuttingDown) {
            val line = try {
                r.readLine()
            } catch (e: SocketTimeoutException) {
                continue
            } catch (e: IOException) {
                return false
            }
            if (line == null) return false
            if (line.contains(token)) return true
        }
        return false
    }

    private fun searchOnce(fen: String) {
        val r = reader ?: throw IOException("reader is null")
        val lines = LinkedHashMap<Int, MutableAnalysisLine>()

        if (appliedHash != hashMb) {
            sendCommand("setoption name Hash value $hashMb")
            appliedHash = hashMb
        }
        if (app

liedThreads != threads) {
            sendCommand("setoption name Threads value $threads")
            appliedThreads = threads
        }
        sendCommand("position fen $fen")
        sendCommand("go depth $searchDepth")

        val deadline = System.currentTimeMillis() + 60000
        while (System.currentTimeMillis() < deadline && !shuttingDown) {
            val line: String? = try {
                r.readLine()
            } catch (e: SocketTimeoutException) {
                continue
            }
            if (line == null) throw IOException("远程引擎连接已断开")

            val tokens = line.trim().split(Regex("\\s+"))
            if (tokens.isEmpty()) continue

            when (tokens[0]) {
                "info" -> {
                    if (tokens.contains("string")) Log.i(tag, "engine: ${line.trim()}")
                    parseInfo(tokens)?.let { ml ->
                        lines[ml.multiPv] = ml
                        val redGo = try { fen.split(" ")[1] != "b" } catch (e: Exception) { true }
                        listener.onSearchUpdate(
                            AnalysisResult(
                                fen, redGo, null,
                                lines.values.sortedBy { it.multiPv }.map { it.toAnalysisLine() }
                            )
                        )
                    }
                }
                "bestmove" -> {
                    val bm = if (tokens.size > 1) tokens[1] else null
                    val redGo = try { fen.split(" ")[1] != "b" } catch (e: Exception) { true }
                    listener.onSearchDone(
                        AnalysisResult(
                            fen, redGo, bm,
                            lines.values.sortedBy { it.multiPv }.map { it.toAnalysisLine() }
                        )
                    )
                    return
                }
            }
        }

        sendCommand("stop")
        val dl2 = System.currentTimeMillis() + 1500
        while (System.currentTimeMillis() < dl2) {
            val line = try {
                r.readLine()
            } catch (e: SocketTimeoutException) {
                continue
            } ?: return
            val tokens = line.trim().split(Regex("\\s+"))
            if (tokens.isEmpty()) continue
            if (tokens[0] == "bestmove") {
                val bm = if (tokens.size > 1) tokens[1] else null
                val redGo = try { fen.split(" ")[1] != "b" } catch (e: Exception) { true }
                listener.onSearchDone(
                    AnalysisResult(
                        fen, redGo, bm,
                        lines.values.sortedBy { it.multiPv }.map { it.toAnalysisLine() }
                    )
                )
                return
            }
        }
        listener.onSearchDone(
            AnalysisResult(
                fen, true, null,
                lines.values.sortedBy { it.multiPv }.map { it.toAnalysisLine() }
            )
        )
    }

    private class MutableAnalysisLine(val multiPv: Int) {
        var depth = 0
        var scoreCp = 0
        var mateIn: Int? = null
        var pv: List<String> = emptyList()
        fun toAnalysisLine(): AnalysisLine = AnalysisLine(multiPv, depth, scoreCp, mateIn, pv)
    }

    private fun parseInfo(tokens: List<String>): MutableAnalysisLine? {
        var multiPv = 1
        var depth = 0
        var scoreCp: Int? = null
        var mateIn: Int? = null
        var pv: List<String> = emptyList()
        var i = 1
        while (i < tokens.size) {
            when (tokens[i]) {
                "depth" -> if (i + 1 < tokens.size) { depth = tokens[i + 1].toIntOrNull() ?: depth; i++ }
                "multipv" -> if (i + 1 < tokens.size) { multiPv = tokens[i + 1].toIntOrNull() ?: multiPv; i++ }
                "score" -> {
                    if (i + 2 < tokens.size) {
                        when (tokens[i + 1]) {
                            "cp" -> { scoreCp = tokens[i + 2].toIntOrNull

() ?: 0; i += 2 }
                            "mate" -> { mateIn = tokens[i + 2].toIntOrNull(); scoreCp = 0; i += 2 }
                        }
                    }
                }
                "pv" -> { pv = tokens.subList(i + 1, tokens.size).filter { it.length == 4 }; i = tokens.size }
                "currmove" -> i = tokens.size
            }
            i++
        }
        if (scoreCp == null && mateIn == null) return null
        return MutableAnalysisLine(multiPv).apply {
            this.depth = depth
            this.scoreCp = scoreCp ?: 0
            this.mateIn = mateIn
            this.pv = pv
        }
    }

    override fun request(fen: String) {
        pendingFen = fen
        if (ready) sendCommand("stop")
        synchronized(lock) { lock.notifyAll() }
    }

    override fun shutdown() {
        shuttingDown = true
        ready = false
        synchronized(lock) { lock.notifyAll() }
        try { sendCommand("quit") } catch (e: Exception) { }
        closeSocket()
        executor.shutdownNow()
    }

    private fun sendCommand(cmd: String) {
        val w = writer ?: return
        synchronized(writeLock) {
            try {
                w.write(cmd)
                w.write("\n")
                w.flush()
            } catch (e: IOException) {
                Log.e(tag, "sendCommand failed: $cmd", e)
            }
        }
    }

    private fun closeSocket() {
        try { reader?.close() } catch (e: Exception) { }
        try { writer?.close() } catch (e: Exception) { }
        try { socket?.close() } catch (e: Exception) { }
        reader = null
        writer = null
        socket = null
    }
}

package com.timez.chess.assist.ui

import android.app.Dialog
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.view.WindowManager
import android.widget.Button
import android.widget.EditText
import android.widget.ProgressBar
import android.widget.TextView
import androidx.fragment.app.DialogFragment
import com.timez.chess.R
import com.timez.chess.assist.AssistConfig
import com.timez.chess.assist.RemoteEngineTester

/**
 * 远程对弈配置对话框：输入 IP/端口 → 测试连接 → 成功后回调 onConnected。
 */
class RemoteEngineDialog : DialogFragment() {

    /** 连接成功回调（在 UI 线程） */
    var onConnected: (() -> Unit)? = null

    private lateinit var config: AssistConfig
    private lateinit var etHost: EditText
    private lateinit var etPort: EditText
    private lateinit var tvError: TextView
    private lateinit var btnConnect: Button
    private lateinit var progress: ProgressBar

    private val mainHandler = Handler(Looper.getMainLooper())

    override fun onCreateDialog(savedInstanceState: Bundle?): Dialog {
        val dialog = super.onCreateDialog(savedInstanceState)
        dialog.setCanceledOnTouchOutside(false)
        return dialog
    }


    override fun onStart() {
        super.onStart()
        dialog?.window?.let { window ->
            val dm = resources.displayMetrics
            val width = (dm.widthPixels * 0.88f).toInt()
            window.setLayout(width, WindowManager.LayoutParams.WRAP_CONTENT)
        }
    }

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?
    ): View {
        config = AssistConfig(requireContext())
        val root = inflater.inflate(R.layout.dialog_remote_engine, container, false)
        etHost = root.findViewById(R.id.et_host)
        etPort = root.findViewById(R.id.et_port)
        tvError = root.findViewById(R.id.tv_error)
        btnConnect = root.findViewById(R.id.btn_connect)
        progress = root.findViewById(R.id.progress)

        etHost.setText(config.remoteHost)
        etPort.setText(if (config.remotePort > 0) config.remotePort.toString() else "10000")

        btnConnect.setOnClickListener { tryConnect() }
        root.findViewById<Button>(R.id.btn_cancel).setOnClickListener { dismiss() }
        return root
    }

    private fun tryConnect() {
        val host = etHost.text.toString().trim()
        val port = etPort.text.toString().trim().toIntOrNull() ?: 0

        if (host.isBlank()) { showError("请填写电脑 IP 地址"); return }
        if (port !in 1..65535) { showError("端口号无效（应为 1–65535）"); return }

        setLoading(true)
        tvError.visibility = View.GONE

        Thread {
            val err = RemoteEngineTester.test(host, port)
            mainHandler.post {
                setLoading(false)
                if (err == null) {
                    config.engineMode = "remote"
                    config.remoteHost = host
                    config.remotePort = port
                    onConnected?.invoke()
                    dismiss()
                } else {
                    showError(err)
                }
            }
        }.start()
    }

    private fun setLoading(loading: Boolean) {
        progress.visibility = if (loading) View.VISIBLE else View.GONE
        btnConnect.isEnabled = !loading
        etHost.isEnabled = !loading
        etPort.isEnabled = !loading
        btnConnect.text = if (loading) "连接中…" else "连接"
    }

    private fun showError(msg: String) {
        tvError.text = msg
        tvError.visibility = View.VISIBLE
    }
}

package com.timez.chess.assist

import android.util.Log
import java.io.BufferedReader
import java.io.BufferedWriter
import java.io.InputStreamReader
import java.io.OutputStreamWriter
import java.net.ConnectException
import java.net.InetSocketAddress
import java.net.Socket
import java.net.SocketTimeoutException
import java.net.UnknownHostException

/**
 * 远程引擎连接测试：TCP 连接 + UCI 握手（uci/uciok + isready/readyok）。
 * 成功返回 null，失败返回错误消息。
 */
object RemoteEngineTester {

    private const val TAG = "RemoteEngineTester"

    /**
     * 测试远程引擎是否可用。
     * @return null 表示成功；非 null 为错误提示文本
     */
    fun test(host: String, port: Int, timeoutMs: Int = 5000): String? {
        if (host.isBlank()) return "请填写电脑 IP 地址"
        if (port !in 1..65535) return "端口号无效（应为 1–65535）"

        var socket: Socket? = null
        var reader: BufferedReader? = null
        var writer: BufferedWriter? = null
        return try {
            socket = Socket().apply {
                connect(InetSocketAddress(host, port), timeoutMs)
                soTimeout = timeoutMs
                tcpNoDelay = true
            }
            reader = BufferedReader(InputStreamReader(socket.getInputStream()))
            writer = BufferedWriter(OutputStreamWriter(socket.getOutputStream()))

            // UCI 握手
            writer.write("uci\n"); writer.flush()
            if (!waitFor(reader, "uciok", timeoutMs)) {
                return "引擎无响应（未收到 uciok），请确认电脑端 RemoteUCI 已启动"
            }

            writer.write("isready\n"); writer.flush()
            if (!waitFor(reader, "readyok", timeoutMs)) {
                return "引擎未就绪（未收到 readyok），请检查电脑端皮卡鱼是否正常加载"
            }
            null
        } catch (e: SocketTimeoutException) {
            "连接超时：请检查 IP/端口是否正确、手机与电脑是否在同一 Wi-Fi"
        } catch (e: ConnectException) {
            "连接被拒绝：请确认电脑端 RemoteUCI 正在运行，且防火墙已放行端口 $port"
        } catch (e: UnknownHostException) {
            "无法解析主机名：请检查 IP 地址是否填写正确"
        } catch (e: Exception) {
            Log.e(TAG, "test failed", e)
            "连接失败：${e.message ?: "未知错误"}"
        } finally {
            try { reader?.close() } catch (_: Exception) {}
            try { writer?.close() } catch (_: Exception) {}
            try { socket?.close() } catch (_: Exception) {}
        }
    }

    private fun waitFor(reader: BufferedReader, token: String, timeoutMs: Int): Boolean {
        val deadline = System.currentTimeMillis() + timeoutMs
        while (System.currentTimeMillis() < deadline) {
            val line = reader.readLine() ?: return false
            if (line.contains(token)) return true
        }
        return false
    }
}

ng? = null
    @Volatile private var stableSince = 0L
    @Volatile private var searchSettled = false

    @Volatile private var currentFen = ""
    @Volatile private var currentPieces: IntArray? = null
    @Volatile private var currentCanonical: Array<IntArray>? = null
    private var currentOrientation = Orientation.STANDARD
    private var lastAnalysis: AnalysisResult? = null
    private var selectedCandidate = 0

    private var bookMoves: List<BookData>? = null
    private var openBook: BHOpenBook? = null
    private var openBookFailed = false

    private class HistoryEntry(val result: RecognitionResult, val redGo: Boolean, val fen: String)
    private val history = ArrayDeque<HistoryEntry>()

    private val strengthLevels = listOf("快速·深度12" to 12, "标准·深度20" to 20, "强劲·深度24" to 24)
    private var strengthIndex = 0
    private val hashLevels = listOf(256, 512, 1024, 2048)
    private var hashIndex = 0

    private var windowManager: WindowManager? = null
    private var overlayPanel: OverlayPanelView? = null
    private var overlayParams: WindowManager.LayoutParams? = null

    private val binder = CastBinder()

    override fun onCreate() {
        super.onCreate()
        tracker = BoardTracker(config.confirmCount)
        val idx = strengthLevels.indexOfFirst { it.second == config.searchDepth }
        strengthIndex = if (idx >= 0) idx else 1
        val hidx = hashLevels.indexOfFirst { it == config.hashMb }
        hashIndex = if (hidx >= 0) hidx else 0
        yoloDetector = try {
            YoloBoardDetector(this)
        } catch (t: Throwable) {
            Log.w(TAG, "yolo detector init failed", t)
            null
        }
        Log.i(TAG, "yolo detector: ${if (yoloDetector != null) "ready" else "unavailable"}")
    }

    override fun onBind(intent: Intent?): IBinder = binder

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        if (intent?.action == ACTION_START) {
            val resultCode = intent.getIntExtra(EXTRA_RESULT_CODE, 0)
            @Suppress("DEPRECATION")
            val data = if (Bui

ld.VERSION.SDK_INT >= 33)
                intent.getParcelableExtra(EXTRA_RESULT_DATA, Intent::class.java)
            else intent.getParcelableExtra(EXTRA_RESULT_DATA)
            startForegroundInternal()
            startCapture(resultCode, data)
        }
        return START_STICKY
    }

    private fun startForegroundInternal() {
        createChannel()
        val notification = buildNotification()
        val type = if (Build.VERSION.SDK_INT >= 29)
            ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION else 0
        ServiceCompat.startForeground(this, NOTIF_ID, notification, type)
    }

    private fun createChannel() {
        val nm = getSystemService(NotificationManager::class.java)
        val ch = NotificationChannel(CHANNEL_ID, "连线·屏幕识别", NotificationManager.IMPORTANCE_LOW)
        ch.description = "屏幕识别与悬浮窗指导运行中"
        nm.createNotificationChannel(ch)
    }

    private fun buildNotification(contentText: String? = null): Notification {
        val pi = PendingIntent.getActivity(
            this, 0,
            Intent(this, AssistActivity::class.java),
            PendingIntent.FLAG_IMMUTABLE
        )
        return Notification.Builder(this, CHANNEL_ID)
            .setContentTitle("timez37·连线识别运行中")
            .setContentText(contentText ?: "仅识别局面并给出走法建议，不会自动走子")
            .setSmallIcon(R.drawable.ic_launcher)
            .setOngoing(true)
            .setContentIntent(pi)
            .build()
    }

    // ==================== 截屏 ====================

    private fun startCapture(resultCode: Int, data: Intent?) {
        if (mediaProjection != null || data == null) return
        overlayClosed = false
        paused = false
        val metrics = screenMetrics()
        val w = metrics.widthPixels
        val h = metrics.heightPixels
        val dpi = metrics.densityDpi

        mediaProjection = projectionManager.getMediaProjection(resultCode, data)
        config.frameSize = w to h
        val reader = ImageReader.newInstance(w, h, PixelFormat.RGBA_8888, 2)
        reader.setOnImageAvailableListener(::onImageAvailable, frameHandler)
        imageReader = reader
        virtualDisplay = mediaProjection?.createVirtualDisplay(
            "assist-capture", w, h, dpi,
            DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,
            reader.surface, null, workerHandler
        )
        Log.i(TAG, "capture started: ${w}x$h")

        val engineMode = config.engineMode
        analysisEngine = when (engineMode) {
            "remote" -> RemoteAnalysisEngine(
                host = config.remoteHost,
                port = config.remotePort,
                listener = analysisListener,
                initialDepth = config.searchDepth,
                initialThreads = config.threads
            )
            else -> AnalysisEngine(
                this, analysisListener, config.searchDepth,
                initialThreads = config.threads
            )
        }
        analysisEngine?.setHash(config.hashMb)
        analysisEngine?.start()
        postRender()
    }

    @Suppress("DEPRECATION")
    private fun screenMetrics(): DisplayMetrics {
        val dm = DisplayMetrics()
        val wm = getSystemService(WINDOW_SERVICE) as WindowManager
        @Suppress("DEPRECATION")
        wm.defaultDisplay.getRealMetrics(dm)
        return dm
    }

    private fun onImageAvailable(reader: ImageReader) {
        val now = System.currentTimeMillis()
        val slowPath = !userDragging && overlayIntersectsBoard()
        val interval = if (slowPath) OVERLAY_FRAME_INTERVAL_MS else MIN_FRAME_INTERVAL_MS
        if (now - lastFrameTs < interval) {
            reader.acquireLatestImage()?.close()
            return
        }
        lastFrameTs = now
        var needRestoreHide = false
        try {
            val needHide = slowPath && (overlayPanel?.alpha ?: 0f) > 0f
            if (needHide) {
                mainHandler.post { overlayPanel?.alpha = 0f }
                needRestoreHide = true

         Thread.sleep(60)
        }
        val image = reader.acquireLatestImage() ?: return
        try {
            val frame = imageToFrame(image)
            if (!pendingFrame) {
                pendingFrame = true
                workerHandler.post { pendingFrame = false; handleFrame(frame) }
            }
        } finally {
            image.close()
        }
    } catch (e: Exception) {
        Log.w(TAG, "onImageAvailable failed", e)
    } finally {
        if (needRestoreHide) {
            mainHandler.post { overlayPanel?.alpha = 1f }
        }
    }
}

private var frameRowBytes: ByteArray? = null

private fun imageToFrame(image: Image): Frame {
    val plane = image.planes[0]
    val rowStride = plane.rowStride
    val pixelStride = plane.pixelStride
    val buffer = plane.buffer
    val w = image.width
    val h = image.height
    val px = IntArray(w * h)
    if (pixelStride == 4) {
        var row = frameRowBytes
        if (row == null || row.size < w * 4) row = ByteArray(w * 4)
        frameRowBytes = row
        var p = 0
        for (y in 0 until h) {
            buffer.position(y * rowStride)
            buffer.get(row, 0, w * 4)
            var i = 0
            while (i < w * 4) {
                px[p++] = (0xFF shl 24) or
                        ((row[i].toInt() and 0xFF) shl 16) or
                        ((row[i + 1].toInt() and 0xFF) shl 8) or
                        (row[i + 2].toInt() and 0xFF)
                i += 4
            }
        }
    } else {
        for (y in 0 until h) {
            val rowStart = y * rowStride
            for (x in 0 until w) {
                val off = rowStart + x * pixelStride
                val r = buffer.get(off).toInt() and 0xFF
                val g = buffer.get(off + 1).toInt() and 0xFF
                val b = buffer.get(off + 2).toInt() and 0xFF
                px[y * w + x] = (0xFF shl 24) or (r shl 16) or (g shl 8) or b
            }
        }
    }
    return Frame(w, h, px)
}

private fun debugSaveFrameIfRequested(frame: Frame) {
    if (!BuildConfig.DEBUG) return
    val trigger = File("/sdcard/assist_debug_save")
    if (!trigger.exists()) return
    trigger.delete()
    try {
        val dir = getExternalFilesDir(null) ?: filesDir
        val outPath = File(dir, "assist_frame.raw").absolutePath
        DataOutputStream(FileOutputStream(outPath)).use { out ->
            out.writeInt(0x41534652)
            out.writeInt(frame.width)
            out.writeInt(frame.height)
            for (p in frame.argb) {
                out.writeByte((p shr 16) and 0xFF)
                out.writeByte((p shr 8) and 0xFF)
                out.writeByte(p and 0xFF)
            }
        }
        Log.i(TAG, "debug frame saved $outPath")
    } catch (e: Exception) {
        Log.w(TAG, "debug frame save failed", e)
    }
}

